INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 584, '가상화 상황집(2): IP 없는 VM, 마이그레이션 실패, 느린 VM, 스냅샷 체인, 종료 안 됨', 'VM 은 켜졌는데 IP 가 없을 때 MAC 으로 DHCP 임대를 찾고, 공유 스토리지 없이 마이그레이션이 막힐 때의 옵션, CPU 대기(%ST)로 오버커밋을 의심하는 법, qemu-img 로 스냅샷 체인과 이미지 상태를 읽는 법, 게스트가 정상 종료하지 않을 때 쓰는 명령을 현장 출력(샘플)에서 읽고 적어 보는 상황집입니다. 샌드박스에는 libvirt·qemu-img 가 없어 샘플 출력을 읽는 방식입니다.', 'linux', '가상화'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 584);
UPDATE quest_set SET display_order = 844, unit_id = (SELECT id FROM unit WHERE id = 72), icon = '🧯' WHERE id = 584;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 1, 'MAC 으로 IP 찾기', '`/tmp/domiflist.log` 는 VM `web01` 의 가상 NIC 목록(`virsh domiflist`)이고, `/tmp/leases.log` 는 가상 네트워크의 DHCP 임대 목록(`virsh net-dhcp-leases`)입니다. VM 의 MAC 주소로 임대 목록에서 **`web01` 이 받은 IP 주소**(서브넷 표기 `/24` 제외)를 찾아 `/tmp/web01_ip.txt` 에 저장하세요. (주소만)', '두 파일 모두 MAC 주소가 열쇠입니다. 호스트 이름 열은 비어 있을 수 있으니 MAC 으로 맞춰 보세요.', 'cat /tmp/domiflist.log /tmp/leases.log
MAC=$(grep vnet3 /tmp/domiflist.log | awk ''{print $5}'')
grep "$MAC" /tmp/leases.log | awk ''{print $5}'' | cut -d/ -f1 > /tmp/web01_ip.txt
cat /tmp/web01_ip.txt

# 게스트가 호스트 이름을 알리지 않는 경우가 많아 MAC 으로 찾는다. VM 에 IP 가 안 보일 때 임대 목록에 그 MAC 이 있는지 보면 DHCP 문제인지 게스트 내부 문제인지 가른다. 임대는 있는데 게스트가 못 받으면 게스트 NIC 설정을 본다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model    MAC\\n-------------------------------------------------------\\n vnet3       network   default   virtio   52:54:00:aa:bb:01\\nEOF\\ncat > /tmp/leases.log <<''EOF''\\n Expiry Time           MAC address         Protocol   IP address       Hostname   Client ID or DUID\\n-----------------------------------------------------------------------------------------------------\\n 2026-11-20 10:30:00   52:54:00:aa:bb:02   ipv4       192.0.2.102/24   db01       -\\n 2026-11-20 10:35:00   52:54:00:aa:bb:01   ipv4       192.0.2.101/24   -          -\\nEOF\\ncat > /tmp/migrate_err.log <<''EOF''\\nerror: Unsafe migration: Migration without shared storage is unsafe\\nEOF\\ncat > /tmp/stats.log <<''EOF''\\nVM      %CPU   %ST   %IOWAIT\\nweb01     20     2        1\\ndb01      35    28        2\\nbatch     90     1        0\\nEOF\\ncat > /tmp/chain.log <<''EOF''\\nimage: snap2.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: snap1.qcow2\\n\\nimage: snap1.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: base.qcow2\\n\\nimage: base.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nEOF\\ncat > /tmp/check.log <<''EOF''\\nERROR cluster 12 refcount=0 reference=1\\nERROR cluster 13 refcount=0 reference=1\\nLeaked cluster 100 refcount=1 reference=0\\nLeaked cluster 101 refcount=1 reference=0\\nLeaked cluster 102 refcount=1 reference=0\\n\\n2 errors were found on the image.\\nData may be corrupted, or further writes to the image may corrupt it.\\n\\n3 leaked clusters were found on the image.\\nThis means waste of disk space, but no harm to data.\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/web01_ip.txt)\\" = 192.0.2.101 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "192.0.2.101 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/web01_ip.txt)\\" = 192.0.2.101 ]"]}]', '[{"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}, {"title": "qemu-img 문서", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 2, '마이그레이션 명령 적기', '`/tmp/migrate_err.log` 와 같이 공유 스토리지가 없는 환경에서 **실행 중인 VM `web01` 을 다른 호스트 `dest.example.com` 으로 옮기려** 합니다. 디스크도 함께 복사해서 옮기는 `virsh migrate` 명령 한 줄을 `/tmp/migrate.txt` 에 적으세요. (실행 중 이동, 디스크 전체 복사, 대상 `qemu+ssh://dest.example.com/system`)', '`virsh migrate --help` 에서 실행 중에 옮기는 옵션과 스토리지를 함께 복사하는 옵션을 찾으세요. 대상은 연결 URI 로 지정합니다.', 'cat /tmp/migrate_err.log
echo ''virsh migrate --live --copy-storage-all web01 qemu+ssh://dest.example.com/system'' > /tmp/migrate.txt
cat /tmp/migrate.txt

# 디스크 복사 옵션을 쓰려면 대상 호스트에 같은 경로·같은 크기의 빈 이미지를 미리 만들어 둬야 한다(libvirt 가 만들지 않는다). 공유 스토리지가 있으면 디스크 복사 옵션이 필요 없다. 변경분만 복사하는 --copy-storage-inc 도 있다. 두 호스트의 CPU 모델 호환도 확인해야 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model    MAC\\n-------------------------------------------------------\\n vnet3       network   default   virtio   52:54:00:aa:bb:01\\nEOF\\ncat > /tmp/leases.log <<''EOF''\\n Expiry Time           MAC address         Protocol   IP address       Hostname   Client ID or DUID\\n-----------------------------------------------------------------------------------------------------\\n 2026-11-20 10:30:00   52:54:00:aa:bb:02   ipv4       192.0.2.102/24   db01       -\\n 2026-11-20 10:35:00   52:54:00:aa:bb:01   ipv4       192.0.2.101/24   -          -\\nEOF\\ncat > /tmp/migrate_err.log <<''EOF''\\nerror: Unsafe migration: Migration without shared storage is unsafe\\nEOF\\ncat > /tmp/stats.log <<''EOF''\\nVM      %CPU   %ST   %IOWAIT\\nweb01     20     2        1\\ndb01      35    28        2\\nbatch     90     1        0\\nEOF\\ncat > /tmp/chain.log <<''EOF''\\nimage: snap2.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: snap1.qcow2\\n\\nimage: snap1.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: base.qcow2\\n\\nimage: base.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nEOF\\ncat > /tmp/check.log <<''EOF''\\nERROR cluster 12 refcount=0 reference=1\\nERROR cluster 13 refcount=0 reference=1\\nLeaked cluster 100 refcount=1 reference=0\\nLeaked cluster 101 refcount=1 reference=0\\nLeaked cluster 102 refcount=1 reference=0\\n\\n2 errors were found on the image.\\nData may be corrupted, or further writes to the image may corrupt it.\\n\\n3 leaked clusters were found on the image.\\nThis means waste of disk space, but no harm to data.\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"^[[:space:]]*(sudo )?virsh( (-c|--connect)[ =]?[^ ]+)? migrate \\" /tmp/migrate.txt ) && ( grep -q -- \\"--live\\" /tmp/migrate.txt ) && ( grep -Eq -- \\"--copy-storage-(all|inc)\\" /tmp/migrate.txt ) && ( grep -q \\"web01\\" /tmp/migrate.txt && grep -q \\"qemu+ssh://dest.example.com/system\\" /tmp/migrate.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "virsh migrate 명령이다", "cmd": ["sh", "-c", "grep -Eq \\"^[[:space:]]*(sudo )?virsh( (-c|--connect)[ =]?[^ ]+)? migrate \\" /tmp/migrate.txt"]}, {"label": "실행 중 이동 옵션이 있다", "cmd": ["sh", "-c", "grep -q -- \\"--live\\" /tmp/migrate.txt"]}, {"label": "디스크 복사 옵션이 있다", "cmd": ["sh", "-c", "grep -Eq -- \\"--copy-storage-(all|inc)\\" /tmp/migrate.txt"]}, {"label": "VM 이름과 대상이 맞다", "cmd": ["sh", "-c", "grep -q \\"web01\\" /tmp/migrate.txt && grep -q \\"qemu+ssh://dest.example.com/system\\" /tmp/migrate.txt"]}]', '[{"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}, {"title": "qemu-img 문서", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 3, 'CPU 를 빼앗긴 VM', '`/tmp/stats.log` 는 VM 별 사용률입니다. (VM 별로 정리한 샘플 표입니다. 실제로 steal 은 게스트 안의 `top`·`mpstat` 에서 보입니다.) `%ST` 는 VM 이 CPU 를 쓰고 싶었지만 호스트가 다른 VM 에 주느라 기다린 시간의 비율입니다. **`%ST` 가 가장 높은 VM 의 이름**을 `/tmp/steal.txt` 에 저장하세요.', '헤더 줄을 제외하고 `%ST` 열 값이 가장 큰 줄을 찾으세요. 숫자 정렬이 필요합니다.', 'cat /tmp/stats.log
tail -n +2 /tmp/stats.log | sort -k3 -n -r | head -1 | awk ''{print $1}'' > /tmp/steal.txt
cat /tmp/steal.txt

# db01 은 CPU 사용률은 낮은데 steal 이 높다. 호스트의 vCPU 총합이 물리 코어보다 많은 오버커밋이거나 다른 VM(batch)이 CPU 를 몰아 쓰는 상황이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model    MAC\\n-------------------------------------------------------\\n vnet3       network   default   virtio   52:54:00:aa:bb:01\\nEOF\\ncat > /tmp/leases.log <<''EOF''\\n Expiry Time           MAC address         Protocol   IP address       Hostname   Client ID or DUID\\n-----------------------------------------------------------------------------------------------------\\n 2026-11-20 10:30:00   52:54:00:aa:bb:02   ipv4       192.0.2.102/24   db01       -\\n 2026-11-20 10:35:00   52:54:00:aa:bb:01   ipv4       192.0.2.101/24   -          -\\nEOF\\ncat > /tmp/migrate_err.log <<''EOF''\\nerror: Unsafe migration: Migration without shared storage is unsafe\\nEOF\\ncat > /tmp/stats.log <<''EOF''\\nVM      %CPU   %ST   %IOWAIT\\nweb01     20     2        1\\ndb01      35    28        2\\nbatch     90     1        0\\nEOF\\ncat > /tmp/chain.log <<''EOF''\\nimage: snap2.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: snap1.qcow2\\n\\nimage: snap1.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: base.qcow2\\n\\nimage: base.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nEOF\\ncat > /tmp/check.log <<''EOF''\\nERROR cluster 12 refcount=0 reference=1\\nERROR cluster 13 refcount=0 reference=1\\nLeaked cluster 100 refcount=1 reference=0\\nLeaked cluster 101 refcount=1 reference=0\\nLeaked cluster 102 refcount=1 reference=0\\n\\n2 errors were found on the image.\\nData may be corrupted, or further writes to the image may corrupt it.\\n\\n3 leaked clusters were found on the image.\\nThis means waste of disk space, but no harm to data.\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/steal.txt)\\" = db01 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "db01 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/steal.txt)\\" = db01 ]"]}]', '[{"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}, {"title": "qemu-img 문서", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 4, '스냅샷 체인 읽기', '`/tmp/chain.log` 는 `qemu-img info --backing-chain snap2.qcow2` 의 출력입니다. 각 이미지가 `backing file`(바탕 이미지)을 가리키며 체인을 이룹니다. 아래 두 값을 저장하세요.
- `/tmp/chain_len.txt` : 체인에 있는 **이미지 파일 수**
- `/tmp/base.txt` : 체인의 맨 아래 **기본 이미지 이름**(바탕 이미지가 없는 이미지)', '`image:` 줄이 이미지 하나입니다. 기본 이미지는 다른 이미지가 가리키기만 하고 자신은 바탕 이미지를 가지지 않는 쪽입니다.', 'cat /tmp/chain.log
grep -c ''^image:'' /tmp/chain.log > /tmp/chain_len.txt
grep ''^image:'' /tmp/chain.log | tail -1 | awk ''{print $2}'' > /tmp/base.txt
cat /tmp/chain_len.txt /tmp/base.txt

# 체인이 길수록 읽기가 느려지고 중간 파일 하나가 사라지면 그 위가 모두 쓸모없어진다. 오래된 스냅샷은 commit 으로 합쳐 정리한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model    MAC\\n-------------------------------------------------------\\n vnet3       network   default   virtio   52:54:00:aa:bb:01\\nEOF\\ncat > /tmp/leases.log <<''EOF''\\n Expiry Time           MAC address         Protocol   IP address       Hostname   Client ID or DUID\\n-----------------------------------------------------------------------------------------------------\\n 2026-11-20 10:30:00   52:54:00:aa:bb:02   ipv4       192.0.2.102/24   db01       -\\n 2026-11-20 10:35:00   52:54:00:aa:bb:01   ipv4       192.0.2.101/24   -          -\\nEOF\\ncat > /tmp/migrate_err.log <<''EOF''\\nerror: Unsafe migration: Migration without shared storage is unsafe\\nEOF\\ncat > /tmp/stats.log <<''EOF''\\nVM      %CPU   %ST   %IOWAIT\\nweb01     20     2        1\\ndb01      35    28        2\\nbatch     90     1        0\\nEOF\\ncat > /tmp/chain.log <<''EOF''\\nimage: snap2.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: snap1.qcow2\\n\\nimage: snap1.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: base.qcow2\\n\\nimage: base.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nEOF\\ncat > /tmp/check.log <<''EOF''\\nERROR cluster 12 refcount=0 reference=1\\nERROR cluster 13 refcount=0 reference=1\\nLeaked cluster 100 refcount=1 reference=0\\nLeaked cluster 101 refcount=1 reference=0\\nLeaked cluster 102 refcount=1 reference=0\\n\\n2 errors were found on the image.\\nData may be corrupted, or further writes to the image may corrupt it.\\n\\n3 leaked clusters were found on the image.\\nThis means waste of disk space, but no harm to data.\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/chain_len.txt)\\" = 3 ] ) && ( [ \\"$(cat /tmp/base.txt)\\" = base.qcow2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "체인이 3개다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/chain_len.txt)\\" = 3 ]"]}, {"label": "기본 이미지가 base.qcow2 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/base.txt)\\" = base.qcow2 ]"]}]', '[{"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}, {"title": "qemu-img 문서", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 5, '이미지 점검 결과 읽기', '`/tmp/check.log` 는 `qemu-img check` 의 결과입니다. **오류(손상 가능)** 와 **누수(공간 낭비, 데이터 손상 아님)** 는 다르게 취급합니다. 아래 두 값을 숫자만 저장하세요.
- `/tmp/errors.txt` : 발견된 **오류(errors) 개수**
- `/tmp/leaks.txt` : 발견된 **누수 클러스터(leaked clusters) 개수**', '요약 문장 두 개(`... were found on the image.`)에서 맨 앞 숫자를 뽑으세요. 오류 줄과 누수 줄이 따로 있습니다.', 'cat /tmp/check.log
grep ''errors were found'' /tmp/check.log | awk ''{print $1}'' > /tmp/errors.txt
grep ''leaked clusters were found'' /tmp/check.log | awk ''{print $1}'' > /tmp/leaks.txt
cat /tmp/errors.txt /tmp/leaks.txt

# 실행 중인 VM 의 이미지에는 check 를 하지 않는다(끄거나 읽기 전용으로). 오류(refcount 불일치)는 데이터 손상 가능성이 있어 이미지 백업 후 수리(-r)한다. 누수는 공간만 낭비하며 -r leaks 로 정리할 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model    MAC\\n-------------------------------------------------------\\n vnet3       network   default   virtio   52:54:00:aa:bb:01\\nEOF\\ncat > /tmp/leases.log <<''EOF''\\n Expiry Time           MAC address         Protocol   IP address       Hostname   Client ID or DUID\\n-----------------------------------------------------------------------------------------------------\\n 2026-11-20 10:30:00   52:54:00:aa:bb:02   ipv4       192.0.2.102/24   db01       -\\n 2026-11-20 10:35:00   52:54:00:aa:bb:01   ipv4       192.0.2.101/24   -          -\\nEOF\\ncat > /tmp/migrate_err.log <<''EOF''\\nerror: Unsafe migration: Migration without shared storage is unsafe\\nEOF\\ncat > /tmp/stats.log <<''EOF''\\nVM      %CPU   %ST   %IOWAIT\\nweb01     20     2        1\\ndb01      35    28        2\\nbatch     90     1        0\\nEOF\\ncat > /tmp/chain.log <<''EOF''\\nimage: snap2.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: snap1.qcow2\\n\\nimage: snap1.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: base.qcow2\\n\\nimage: base.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nEOF\\ncat > /tmp/check.log <<''EOF''\\nERROR cluster 12 refcount=0 reference=1\\nERROR cluster 13 refcount=0 reference=1\\nLeaked cluster 100 refcount=1 reference=0\\nLeaked cluster 101 refcount=1 reference=0\\nLeaked cluster 102 refcount=1 reference=0\\n\\n2 errors were found on the image.\\nData may be corrupted, or further writes to the image may corrupt it.\\n\\n3 leaked clusters were found on the image.\\nThis means waste of disk space, but no harm to data.\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/errors.txt)\\" = 2 ] ) && ( [ \\"$(cat /tmp/leaks.txt)\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류가 2개다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/errors.txt)\\" = 2 ]"]}, {"label": "누수가 3개다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/leaks.txt)\\" = 3 ]"]}]', '[{"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}, {"title": "qemu-img 문서", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 6, '에이전트로 정상 종료', 'VM `web01` 에 `shutdown` 을 보냈는데 게스트가 ACPI 신호를 처리하지 않아 계속 running 입니다. 게스트에 설치된 **에이전트를 통해 종료를 요청**하는 `virsh` 명령 한 줄을 `/tmp/stop.txt` 에 적으세요. (마지막 수단인 강제 종료 `destroy` 는 쓰지 않습니다)', '`virsh shutdown` 에는 종료 신호를 어떤 방식으로 보낼지 정하는 모드 옵션이 있습니다.', 'echo ''virsh shutdown --mode agent web01'' > /tmp/stop.txt
cat /tmp/stop.txt

# 에이전트(qemu-guest-agent)가 설치돼 있어야 동작한다. 그래도 안 되면 마지막으로 destroy(전원을 뽑는 것과 같음)를 쓰고, 그 전에 데이터 손상 가능성을 고려한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model    MAC\\n-------------------------------------------------------\\n vnet3       network   default   virtio   52:54:00:aa:bb:01\\nEOF\\ncat > /tmp/leases.log <<''EOF''\\n Expiry Time           MAC address         Protocol   IP address       Hostname   Client ID or DUID\\n-----------------------------------------------------------------------------------------------------\\n 2026-11-20 10:30:00   52:54:00:aa:bb:02   ipv4       192.0.2.102/24   db01       -\\n 2026-11-20 10:35:00   52:54:00:aa:bb:01   ipv4       192.0.2.101/24   -          -\\nEOF\\ncat > /tmp/migrate_err.log <<''EOF''\\nerror: Unsafe migration: Migration without shared storage is unsafe\\nEOF\\ncat > /tmp/stats.log <<''EOF''\\nVM      %CPU   %ST   %IOWAIT\\nweb01     20     2        1\\ndb01      35    28        2\\nbatch     90     1        0\\nEOF\\ncat > /tmp/chain.log <<''EOF''\\nimage: snap2.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: snap1.qcow2\\n\\nimage: snap1.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nbacking file: base.qcow2\\n\\nimage: base.qcow2\\nfile format: qcow2\\nvirtual size: 20 GiB (21474836480 bytes)\\nEOF\\ncat > /tmp/check.log <<''EOF''\\nERROR cluster 12 refcount=0 reference=1\\nERROR cluster 13 refcount=0 reference=1\\nLeaked cluster 100 refcount=1 reference=0\\nLeaked cluster 101 refcount=1 reference=0\\nLeaked cluster 102 refcount=1 reference=0\\n\\n2 errors were found on the image.\\nData may be corrupted, or further writes to the image may corrupt it.\\n\\n3 leaked clusters were found on the image.\\nThis means waste of disk space, but no harm to data.\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"^[[:space:]]*(sudo )?virsh shutdown \\" /tmp/stop.txt ) && ( grep -Eq -- \\"--mode[= ]agent\\" /tmp/stop.txt ) && ( grep -q \\"web01\\" /tmp/stop.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "virsh shutdown 이다", "cmd": ["sh", "-c", "grep -Eq \\"^[[:space:]]*(sudo )?virsh shutdown \\" /tmp/stop.txt"]}, {"label": "에이전트 모드다", "cmd": ["sh", "-c", "grep -Eq -- \\"--mode[= ]agent\\" /tmp/stop.txt"]}, {"label": "대상이 web01 이다", "cmd": ["sh", "-c", "grep -q \\"web01\\" /tmp/stop.txt"]}]', '[{"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}, {"title": "qemu-img 문서", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 7, '공유 스토리지 없는 마이그레이션', '공유 스토리지 없이 `virsh migrate --live` 만 실행했더니 "Migration without shared storage is unsafe" 오류가 납니다. 이 오류의 의미로 가장 알맞은 것은?', '두 호스트가 같은 디스크 파일을 볼 수 있는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["VM 의 메모리가 너무 커서 이동할 수 없다", "대상 호스트의 네트워크 카드가 고장 났다", "대상이 디스크 이미지를 볼 수 없어 디스크도 복사해야 한다", "소스 호스트의 libvirt 가 오래되었다"]', 2, '실행 중 마이그레이션은 메모리 상태를 옮기며, 디스크는 두 호스트가 공유하는 스토리지에 있다고 가정합니다. 공유가 없으면 대상은 디스크를 볼 수 없으므로 `--copy-storage-all`(전체) 또는 `--copy-storage-inc`(증분) 로 디스크도 함께 복사해야 합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 8, 'steal 시간의 의미', '게스트 VM 의 CPU 통계에서 `%st`(steal)가 높고 호스트의 물리 CPU 는 포화 상태입니다. 가장 알맞은 해석은?', 'VM 이 CPU 를 원했는데 받지 못한 시간입니다.', NULL, NULL, '[]', 'choice', '["게스트 OS 안의 프로세스가 CPU 를 과도하게 쓰고 있다", "여러 VM 이 CPU 를 나눠 쓰느라 이 VM 이 CPU 를 기다린다", "게스트 메모리가 부족해 디스크로 스왑 중이다", "게스트의 네트워크 지연이 높다"]', 1, 'steal 은 가상 CPU 가 실행되고 싶었지만 호스트가 다른 VM 에 물리 CPU 를 주고 있어 기다린 시간입니다. 호스트의 vCPU 오버커밋이나 시끄러운 이웃 VM 이 원인이므로 VM 배치·CPU 할당을 조정합니다. 게스트 내부 프로세스 문제라면 %us·%sy 가 높게 나옵니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 9, '스냅샷 체인 전체 보기', '이미지의 바탕 이미지까지 **체인 전체**를 한 번에 보려면 `qemu-img info` 에 어떤 옵션을 줘야 할까요? 빈칸을 채우세요.', '`qemu-img info --help` 의 옵션 목록에서 바탕 이미지와 관련된 것을 찾으세요.', NULL, NULL, '[]', 'fill', '["backing-chain", "output=json", "force-share", "image-opts"]', NULL, '`--backing-chain` 은 이미지가 가리키는 모든 바탕 이미지를 이어서 보여 줍니다. `--output=json` 은 출력 형식, `--force-share` 는 다른 프로세스가 쓰는 이미지를 읽기 위한 옵션, `--image-opts` 는 이미지 지정 방식입니다.', '[0]', 'qemu-img info --{0} snap2.qcow2', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 584, 10, '스냅샷 체인 정리 순서', '오래 쌓인 스냅샷 체인을 정리해(오버레이를 아래 이미지에 합쳐) 줄이려 합니다. 합친 뒤에는 결과를 검증합니다. 올바른 순서로 놓으세요.', '어떤 파일을 합칠지 정해야 백업 대상도 정해집니다.', NULL, NULL, '[]', 'order', '["합친 뒤 `qemu-img check` 로 정상 여부를 확인한다", "`commit`(실행 중이면 `blockcommit`)으로 오버레이를 아래 이미지에 합친다", "`qemu-img info --backing-chain` 으로 합칠 오버레이를 정한다", "합칠 이미지 파일을 복사해 백업해 둔다"]', NULL, '체인 구조를 먼저 알아야 어떤 파일을 합칠지 정할 수 있고, 합치기는 되돌리기 어려워 백업을 먼저 만들어 둡니다. 합친 뒤에는 이미지 검사로 정상 여부를 확인합니다.', '[2, 3, 1, 0]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 584 AND order_index = 10);
